function extract($, ctx) {
  const items = [];

  // ----- Try JSON‑LD first -----
  $('script[type="application/ld+json"]').each((_, el) => {
    let data;
    try {
      data = JSON.parse($(el).text());
    } catch (_) {
      return;
    }
    // walk the JSON looking for a Menu object
    function walk(obj) {
      if (!obj || typeof obj !== 'object') return;
      if (Array.isArray(obj)) {
        obj.forEach(walk);
        return;
      }
      if (obj['@type'] === 'Menu') {
        processMenu(obj);
        return;
      }
      for (const key in obj) {
        walk(obj[key]);
      }
    }
    walk(data);
  });

  // ----- Fallback to DOM parsing if JSON‑LD yielded nothing -----
  if (items.length === 0) {
    $('#menu-root .menu-group').each((_, sectEl) => {
      const $sect = $(sectEl);
      const sectionHeading = $sect.find('.menu-group__title').first().text();
      const section = cleanText(sectionHeading) || null;

      $sect.find('.dish').each((_, dishEl) => {
        const $dish = $(dishEl);
        const nameRaw = $dish.find('.dish__name').text();
        if (!nameRaw) return;
        const name = cleanText(nameRaw);
        const descRaw = $dish.find('.dish__desc').text();
        const description = descRaw ? cleanText(descRaw) : null;
        const priceRaw = $dish.find('.dish__price').text();
        const price = priceRaw ? parsePrice(priceRaw) : null;
        items.push({ section, name, description: description ?? null, price });
      });
    });
  }

  // ----- Deduplicate exact duplicates (mobile/desktop copies) -----
  const seen = new Set();
  const deduped = [];
  for (const it of items) {
    const key = `${it.section}|${it.name}|${it.description}|${it.price}`;
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(it);
    }
  }
  return deduped;

  // ----- Helper to process a Menu object from JSON‑LD -----
  function processMenu(menu) {
    if (!menu || !menu.hasMenuSection) return;
    menu.hasMenuSection.forEach(sec => {
      const sectionName = cleanText(sec.name) || null;
      if (!sec.hasMenuItem) return;
      sec.hasMenuItem.forEach(item => {
        const nameRaw = item.name;
        if (!nameRaw) return;
        const name = cleanText(nameRaw);
        const descriptionRaw = item.description;
        const description = descriptionRaw ? cleanText(descriptionRaw) : null;
        let price = null;
        if (item.offers) {
          const offers = Array.isArray(item.offers) ? item.offers : [item.offers];
          for (const off of offers) {
            if (off && off.price !== undefined) {
              price = parsePrice(String(off.price));
              break;
            }
          }
        }
        items.push({ section: sectionName, name, description: description ?? null, price });
      });
    });
  }
}
